// ================================================================================================
// ===== Helpers ==================================================================================
// ================================================================================================

/// The maximum number of tokens read from one source (protects against a lexer that never
/// returns TOK_EOF).
#define MAX_TOKENS 50000

/// The number of elements of a static array.
#define DIM(arr) (sizeof(arr) / sizeof((arr)[0]))

/// A list of tokens read from one source, ending with the first TOK_EOF (if any was produced).
typedef struct {
    token_t *items;
    size_t len;
} tokens_t;

/// Tokenizes the whole source (up to and including the first TOK_EOF).
static tokens_t lex_all(const char *src) {
    string_t s;
    str_init_from(&s, src);

    lexer_t lex;
    lexer_init(&lex, &s);

    tokens_t toks = {.items = nullptr, .len = 0};
    size_t cap    = 0;

    while (toks.len < MAX_TOKENS) {
        if (toks.len == cap) {
            cap        = cap == 0 ? 16 : cap * 2;
            toks.items = safe_realloc(toks.items, cap * sizeof(token_t));
        }

        token_t tok            = lexer_next(&lex);
        toks.items[toks.len++] = tok;

        if (tok.type == TOK_EOF) {
            break;
        }
    }

    lexer_free(&lex);
    str_free(&s);

    return toks;
}

static void tokens_free(tokens_t *toks) {
    for (size_t i = 0; i < toks->len; i++) {
        token_free(&toks->items[i]);
    }
    free(toks->items);
    toks->items = nullptr;
    toks->len   = 0;
}

/// Reads only the first token of the source. The returned token is owned by the caller.
static token_t lex_first(const char *src) {
    string_t s;
    str_init_from(&s, src);

    lexer_t lex;
    lexer_init(&lex, &s);

    token_t tok = lexer_next(&lex);

    lexer_free(&lex);
    str_free(&s);

    return tok;
}

/// A token type name that is safe to print even if token_type_name is not implemented yet.
static const char *safe_name(token_type_t type) {
    const char *name = token_type_name(type);
    return name != nullptr ? name : "?";
}

/// Compares the types of the tokens with the expected types; prints both sequences on mismatch.
static bool types_match(const char *src, const tokens_t *toks, const token_type_t *exp, size_t n) {
    bool ok = toks->len == n;
    for (size_t i = 0; ok && i < n; i++) {
        ok = toks->items[i].type == exp[i];
    }

    if (!ok) {
        const size_t print_max = 80;

        printf("  Source   : \"%s\"\n", src);
        printf("  Expected (%zu):", n);
        for (size_t i = 0; i < n && i < print_max; i++) {
            printf(" %s(%d)", safe_name(exp[i]), (int)exp[i]);
        }
        printf("\n  Actual   (%zu):", toks->len);
        for (size_t i = 0; i < toks->len && i < print_max; i++) {
            printf(" %s(%d)", safe_name(toks->items[i].type), (int)toks->items[i].type);
        }
        printf("%s\n", toks->len > print_max ? " ..." : "");
    }

    return ok;
}

/**
 * Asserts that the source is tokenized exactly into the given token types (including the final
 * TOK_EOF).
 */
#define ASSERT_TOKENS(src, ...)                                                                    \
    do {                                                                                           \
        const token_type_t exp_[] = {__VA_ARGS__};                                                 \
        tokens_t toks_            = lex_all(src);                                                  \
        bool ok_                  = types_match((src), &toks_, exp_, DIM(exp_));                   \
        tokens_free(&toks_);                                                                       \
        ASSERT_TRUE(ok_);                                                                          \
    } while (0)

/// Asserts the type of a single token (enums are compared as int for utest's printer).
#define ASSERT_TYPE(tok, expected) ASSERT_EQ((int)(tok).type, (int)(expected))

// Set in the forked child, so that LeakSanitizer (if the tests are built with sanitizers) does not
// replace the exit code of an intentionally aborted lexer with its own.
static bool in_death_child = false;

int __lsan_is_turned_off(void);
int __lsan_is_turned_off(void) {
    return in_death_child;
}

/**
 * Tokenizes the whole source in a forked child process (with stderr silenced).
 * @returns The exit code of the child (0 if the whole input was tokenized without an error), -1 if
 * the child was killed by a signal (crash or timeout), -2 if the child could not be run.
 */
static int lex_exit_code(const char *src) {
    fflush(stdout);
    fflush(stderr);

    pid_t pid = fork();
    if (pid < 0) {
        return -2;
    }

    if (pid == 0) {
        in_death_child = true;

        int null_fd = open("/dev/null", O_WRONLY);
        if (null_fd >= 0) {
            dup2(null_fd, STDERR_FILENO);
            close(null_fd);
        }
        alarm(5); // A stuck lexer must not block the test run.

        string_t s;
        str_init_from(&s, src);
        lexer_t lex;
        lexer_init(&lex, &s);

        for (size_t i = 0; i < MAX_TOKENS; i++) {
            token_t tok = lexer_next(&lex);
            bool eof    = tok.type == TOK_EOF;
            token_free(&tok);
            if (eof) {
                break;
            }
        }

        lexer_free(&lex);
        str_free(&s);
        _exit(0);
    }

    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        return -2;
    }

    return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
}

/// Asserts that tokenizing the source ends with a lexical error (exit code 1).
#define ASSERT_LEX_ERROR(src) ASSERT_EQ_MSG(lex_exit_code(src), (int)ERR_LEXICAL, (src))

/// Asserts that the whole source is tokenized without any error.
#define ASSERT_LEX_OK(src) ASSERT_EQ_MSG(lex_exit_code(src), 0, (src))

/// Builds a heap C string made of `count` repetitions of `piece` (caller frees).
static char *repeat(const char *piece, size_t count) {
    string_t s = STR_INIT;
    for (size_t i = 0; i < count; i++) {
        str_append(&s, piece);
    }
    return str_to_owned(&s);
}

