    tok = lex_first("0.1");
    ASSERT_TYPE(tok, TOK_LIT_DOUBLE);
    ASSERT_NEAR(tok.double_val, 0.1, 1e-15);
    token_free(&tok);

    tok = lex_first("1.7976931348623157e308");
